# Parse the product data
def parse_cli_output(output):
    clean = output.strip()
    if '{' in clean:
        json_start = clean.index('{')
        # Find the matching closing brace
        brace_count = 0
        for i, c in enumerate(clean[json_start:], json_start):
            if c == '{': brace_count += 1
            elif c == '}': brace_count -= 1
            if brace_count == 0:
                return json.loads(clean[json_start:i+1])
    elif '[' in clean:
        json_start = clean.index('[')
        return json.loads(clean[json_start:])
    return clean

